  final String b64;
  @override
  State<_ViewOnceImage> createState() => _ViewOnceImageState();
}

class _ViewOnceImageState extends State<_ViewOnceImage> {
  bool _revealed = false;
  bool _viewed = false;
  @override
  Widget build(BuildContext context) {
    if (_viewed)
      return Container(
        height: 64,
        alignment: Alignment.center,
        decoration: BoxDecoration(
          color: Colors.white.withOpacity(0.06),
          borderRadius: BorderRadius.circular(10),
        ),
        child: const Row(
          mainAxisSize: MainAxisSize.min,
          children: [
            Icon(Icons.check_circle_outline, color: Colors.white38, size: 14),
            SizedBox(width: 6),
            Text(
              '📷 Proof viewed',
              style: TextStyle(color: Colors.white38, fontSize: 12),
            ),
          ],
        ),
      );
    // LayoutBuilder ensures bounded width — fixes iOS crash
    return LayoutBuilder(
      builder: (context, constraints) {
        final w = constraints.maxWidth.isFinite
            ? constraints.maxWidth
            : MediaQuery.sizeOf(context).width - 40;
        return GestureDetector(
          onTap: () => setState(() {
            if (!_revealed)
              _revealed = true;
            else
              _viewed = true;
          }),
          child: ClipRRect(
            borderRadius: BorderRadius.circular(14),
            child: SizedBox(
              width: w,
              height: 200,
              child: Stack(
                alignment: Alignment.center,
                children: [
                  Image.memory(
                    base64Decode(widget.b64),
                    width: w,
                    height: 200,
                    fit: BoxFit.cover,
                    gaplessPlayback: true,
                  ),
                  if (!_revealed)
                    Container(
                      width: w,
                      height: 200,
                      color: Colors.black.withOpacity(0.85),
                      alignment: Alignment.center,
                      child: const Column(
                        mainAxisSize: MainAxisSize.min,
                        children: [
                          Icon(
                            Icons.visibility_outlined,
                            color: Colors.white,
                            size: 32,
                          ),
                          SizedBox(height: 6),
                          Text(
                            'Tap to reveal proof photo',
                            style: TextStyle(
                              color: Colors.white,
                              fontSize: 13,
                              fontWeight: FontWeight.w600,
                            ),
                          ),
                          SizedBox(height: 2),
                          Text(
                            'Tap again to dismiss',
                            style: TextStyle(
                              color: Colors.white54,
                              fontSize: 11,
                            ),
                          ),
                        ],
                      ),
                    ),
                  if (_revealed)
                    Positioned(
                      bottom: 8,
                      right: 8,
                      child: GestureDetector(
                        onTap: () => setState(() => _viewed = true),
                        child: Container(
                          padding: const EdgeInsets.symmetric(
                            horizontal: 10,
                            vertical: 5,
                          ),
                          decoration: BoxDecoration(
                            color: Colors.black.withOpacity(0.7),
                            borderRadius: BorderRadius.circular(20),
                          ),
                          child: const Text(
                            'Tap to dismiss',
                            style: TextStyle(color: Colors.white, fontSize: 11),
                          ),
                        ),
                      ),
                    ),
                ],
              ),
            ),
          ),
        );
      },
    );
  }
}

