/// Physical playing-card style widget.
/// - Background: user cover image OR built-in decorative pattern
/// - Bottom strip: when cover exists, shows a blurred thumbnail strip
class _GameCard extends StatelessWidget {
  const _GameCard({
    required this.content,
    required this.color,
    required this.badge,
    this.coverUrl,
    this.isSpicy = false,
    this.playerInitial,
    this.emoji,
    this.subTitle,
  });
  final String content;
  final Color color;
  final String badge;
  final String? coverUrl;
  final bool isSpicy;
  final String? playerInitial;
  final String? emoji;
  final String? subTitle;

  static const _r = 24.0;

  @override
  Widget build(BuildContext context) {
    final hasCover = coverUrl != null && coverUrl!.isNotEmpty;
    return LayoutBuilder(
      builder: (context, constraints) {
        final w = constraints.maxWidth.isFinite
            ? constraints.maxWidth
            : MediaQuery.sizeOf(context).width - 32;
        return AnimatedContainer(
          duration: const Duration(milliseconds: 350),
          width: w,
          decoration: BoxDecoration(
            borderRadius: BorderRadius.circular(_r),
            border: Border.all(color: color.withOpacity(0.55), width: 1.5),
            boxShadow: [
              BoxShadow(
                color: color.withOpacity(0.45),
                blurRadius: 28,
                offset: const Offset(0, 12),
              ),
              BoxShadow(
                color: Colors.black.withOpacity(0.35),
                blurRadius: 12,
                offset: const Offset(0, 4),
              ),
            ],
          ),
          child: ClipRRect(
            borderRadius: BorderRadius.circular(_r - 1),
            child: Stack(
              children: [
                // ── Background ───────────────────────────────────────────────
                Positioned.fill(
                  child: hasCover
                      ? Image.network(
                          coverUrl!,
                          fit: BoxFit.cover,
                          width: double.infinity,
                          height: double.infinity,
                          errorBuilder: (_, __, ___) => Image.asset(
                            'assets/images/backgrounds/jma3a_card_background.png',
                            fit: BoxFit.cover,
                            width: double.infinity,
                            height: double.infinity,
                          ),
                        )
                      : Image.asset(
                          'assets/images/backgrounds/jma3a_card_background.png',
                          fit: BoxFit.cover,
                          width: double.infinity,
                          height: double.infinity,
                          errorBuilder: (_, __, ___) =>
                              _AppPatternBg(color: color),
                        ),
                ),
                // ── Colour tint overlay — keep light so background image shows ──
                Positioned.fill(
                  child: Container(
                    decoration: BoxDecoration(
                      gradient: LinearGradient(
                        colors: [
                          color.withOpacity(0.30),
                          const Color(0xFF0D1B2A).withOpacity(0.45),
                        ],
                        begin: Alignment.topCenter,
                        end: Alignment.bottomCenter,
                      ),
                    ),
                  ),
                ),
                // ── Shimmer lines ────────────────────────────────────────────
                Positioned.fill(
                  child: CustomPaint(painter: _CardShimmerPainter()),
                ),
                // ── Content ──────────────────────────────────────────────────
                Padding(
                  padding: EdgeInsets.fromLTRB(20, 18, 20, hasCover ? 72 : 20),
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Row(
                        children: [
                          _Pill(
                            badge,
                            background: Colors.white.withOpacity(0.22),
                          ),
                          if (isSpicy) ...[
                            const SizedBox(width: 6),
                            _Pill(
                              '🌶 SPICY',
                              background: Colors.red.withOpacity(0.35),
                            ),
                          ],
                          const Spacer(),
                          if (playerInitial != null)
                            Container(
                              width: 30,
                              height: 30,
                              alignment: Alignment.center,
                              decoration: BoxDecoration(
                                color: Colors.white.withOpacity(0.18),
                                shape: BoxShape.circle,
                                border: Border.all(
                                  color: Colors.white.withOpacity(0.35),
                                ),
                              ),
                              child: Text(
                                playerInitial!,
                                style: const TextStyle(
                                  color: Colors.white,
                                  fontWeight: FontWeight.w800,
                                  fontSize: 13,
                                ),
                              ),
                            ),
                        ],
                      ),
                      const Spacer(),
                      if (emoji != null)
                        Text(
                          emoji!,
                          style: const TextStyle(fontSize: 56),
                        ).animate().scale(
                          begin: const Offset(0.5, 0.5),
                          end: const Offset(1, 1),
                          duration: 400.ms,
                          curve: Curves.elasticOut,
                        ),
                      if (subTitle != null) ...[
                        const SizedBox(height: 6),
                        Text(
                          subTitle!,
                          style: TextStyle(
                            color: Colors.white.withOpacity(0.75),
                            fontSize: 12,
                            fontWeight: FontWeight.w700,
                            letterSpacing: 0.8,
                          ),
                        ),
                      ],
                      const SizedBox(height: 10),
                      Text(
                            content,
                            style: const TextStyle(
                              fontSize: 22,
                              fontWeight: FontWeight.w800,
                              color: Colors.white,
                              height: 1.45,
                              shadows: [
                                Shadow(
                                  color: Colors.black54,
                                  blurRadius: 10,
                                  offset: Offset(0, 2),
                                ),
                              ],
                            ),
                          )
                          .animate()
                          .fadeIn(duration: 280.ms)
                          .slideY(begin: 0.06, end: 0),
                      const Spacer(),
                    ],
                  ),
                ),
                // ── Bottom cover strip ───────────────────────────────────────
                if (hasCover)
                  Positioned(
                    left: 0,
                    right: 0,
                    bottom: 0,
                    child: _CardBottomStrip(
                      coverUrl: coverUrl!,
                      accentColor: color,
                    ),
                  ),
                // ── Corner suit symbols ──────────────────────────────────────
                Positioned(
                  top: 10,
                  left: 12,
                  child: Opacity(
                    opacity: 0.18,
                    child: Text(
                      _suitFor(badge),
                      style: const TextStyle(fontSize: 18, color: Colors.white),
                    ),
                  ),
                ),
                Positioned(
                  bottom: hasCover ? 62 : 10,
                  right: 12,
                  child: Opacity(
                    opacity: 0.18,
                    child: RotatedBox(
                      quarterTurns: 2,
                      child: Text(
                        _suitFor(badge),
                        style: const TextStyle(
                          fontSize: 18,
                          color: Colors.white,
                        ),
                      ),
                    ),
                  ),
                ),
              ],
            ),
          ),
        ).animate().scale(
          begin: const Offset(0.92, 0.92),
          end: const Offset(1, 1),
          duration: 320.ms,
          curve: Curves.easeOutBack,
        );
      },
    );
  }

  static String _suitFor(String badge) {
    if (badge.contains('TRUTH')) return '🤔';
    if (badge.contains('DARE')) return '🔥';
    if (badge.contains('NEVER')) return '🍹';
    if (badge.contains('MEME')) return '😂';
    return '🎲';
  }
}

