class _TurnTimer extends StatefulWidget {
  const _TurnTimer({
    required this.startedAt,
    required this.durationSeconds,
    required this.onExpired,
  });
  final int startedAt, durationSeconds;
  final VoidCallback onExpired;
  @override
  State<_TurnTimer> createState() => _TurnTimerState();
}

class _TurnTimerState extends State<_TurnTimer> {
  Timer? _t;
  int _remaining = 0;
  bool _fired = false;
  @override
  void initState() {
    super.initState();
    _update();
    _t = Timer.periodic(1.seconds, (_) => _update());
  }

  void _update() {
    final elapsed =
        (DateTime.now().millisecondsSinceEpoch - widget.startedAt) ~/ 1000;
    final rem = (widget.durationSeconds - elapsed).clamp(
      0,
      widget.durationSeconds,
    );
    if (mounted) setState(() => _remaining = rem);
    if (rem == 0 && !_fired) {
      _fired = true;
      widget.onExpired();
    }
  }

  @override
  void dispose() {
    _t?.cancel();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final pct = widget.durationSeconds > 0
        ? _remaining / widget.durationSeconds
        : 0.0;
    final color = pct > 0.4
        ? _kGreen
        : pct > 0.2
        ? _kOrange
        : _kCoral;
    return Column(
      children: [
        Row(
          mainAxisAlignment: MainAxisAlignment.center,
          children: [
            Icon(Icons.timer_outlined, color: color, size: 16),
            const SizedBox(width: 6),
            Text(
              '$_remaining s',
              style: TextStyle(
                color: color,
                fontWeight: FontWeight.w800,
                fontSize: 18,
              ),
            ),
          ],
        ),
        const SizedBox(height: 4),
        ClipRRect(
          borderRadius: BorderRadius.circular(4),
          child: LinearProgressIndicator(
            value: pct,
            minHeight: 6,
            color: color,
            backgroundColor: color.withOpacity(0.15),
          ),
        ),
      ],
    );
  }
}

// ── In-game history sheet ──────────────────────────────────────────────────────
class _HistorySheet extends StatelessWidget {
  const _HistorySheet({required this.game});
  final OfflineGameProvider game;
  @override
  Widget build(BuildContext context) {
    final state = game.state;
    final session = game.session;
    final names = {
      for (final p in session?.players ?? <OfflinePlayer>[]) p.id: p.name,
    };
    return Container(
      height: MediaQuery.sizeOf(context).height * 0.75,
      decoration: const BoxDecoration(
        color: _kNavyLight,
        borderRadius: BorderRadius.vertical(top: Radius.circular(24)),
      ),
      child: Column(
        children: [
          Container(
            margin: const EdgeInsets.symmetric(vertical: 10),
            width: 36,
            height: 4,
            decoration: BoxDecoration(
              color: Colors.white24,
              borderRadius: BorderRadius.circular(2),
            ),
          ),
          const Text(
            '📖 Game History',
            style: TextStyle(
              color: Colors.white,
              fontWeight: FontWeight.w800,
              fontSize: 16,
            ),
          ),
          const SizedBox(height: 4),
          const Divider(color: Colors.white12, height: 1),
          Expanded(child: _buildHistory(state, names)),
        ],
      ),
    );
  }

  Widget _buildHistory(GameEngineState? state, Map<String, String> names) {
    if (state is TodState) {
      if (state.history.isEmpty)
        return const Center(
          child: Text(
            'No turns completed yet',
            style: TextStyle(color: Colors.white38),
          ),
        );
      return ListView.builder(
        padding: const EdgeInsets.all(12),
        itemCount: state.history.length,
        itemBuilder: (_, i) {
          final r = state.history[state.history.length - 1 - i];
          final pName = names[r.playerId] ?? r.playerId;
          final isTruth = r.card?.type == TodCardType.truth;
          final color = isTruth ? _kCoral : _kOrange;
          return Container(
            margin: const EdgeInsets.only(bottom: 8),
            decoration: BoxDecoration(
              color: Colors.white.withOpacity(0.05),
              borderRadius: BorderRadius.circular(14),
              border: Border.all(color: color.withOpacity(0.15)),
            ),
            child: Column(
              children: [
                Container(
                  padding: const EdgeInsets.symmetric(
                    horizontal: 12,
                    vertical: 8,
                  ),
                  decoration: BoxDecoration(
                    color: color.withOpacity(0.1),
                    borderRadius: const BorderRadius.vertical(
                      top: Radius.circular(14),
                    ),
                  ),
                  child: Row(
                    children: [
                      Text(
                        isTruth ? '🤔' : '🔥',
                        style: const TextStyle(fontSize: 14),
                      ),
                      const SizedBox(width: 8),
                      Expanded(
                        child: Text(
                          pName,
                          style: const TextStyle(
                            color: Colors.white,
                            fontWeight: FontWeight.w700,
                            fontSize: 13,
                          ),
                        ),
                      ),
                      Container(
                        padding: const EdgeInsets.symmetric(
                          horizontal: 8,
                          vertical: 2,
                        ),
                        decoration: BoxDecoration(
                          color: r.response.isNotEmpty
                              ? _kGreen.withOpacity(0.15)
                              : Colors.red.withOpacity(0.15),
                          borderRadius: BorderRadius.circular(8),
                        ),
                        child: Text(
                          r.response.isNotEmpty ? '✓ Done' : '✗ Skipped',
                          style: TextStyle(
                            color: r.response.isNotEmpty ? _kGreen : _kCoral,
                            fontSize: 10,
                            fontWeight: FontWeight.w700,
                          ),
                        ),
                      ),
                    ],
                  ),
                ),
                if (r.card != null)
                  Padding(
                    padding: const EdgeInsets.fromLTRB(12, 8, 12, 4),
                    child: Text(
                      r.card!.content,
                      style: const TextStyle(
                        color: Colors.white70,
                        fontSize: 13,
                      ),
                    ),
                  ),
                if (r.response.isNotEmpty)
                  Padding(
                    padding: const EdgeInsets.fromLTRB(12, 2, 12, 8),
                    child: Text(
                      '"${r.response}"',
                      style: const TextStyle(
                        color: Colors.white54,
                        fontSize: 12,
                        fontStyle: FontStyle.italic,
                      ),
                    ),
                  )
                else
                  const SizedBox(height: 8),
              ],
            ),
          );
        },
      );
    }
    if (state is NhieState) {
      if (state.history.isEmpty)
        return const Center(
          child: Text(
            'No rounds completed yet',
            style: TextStyle(color: Colors.white38),
          ),
        );
      return ListView.builder(
        padding: const EdgeInsets.all(12),
        itemCount: state.history.length,
        itemBuilder: (_, i) {
          final r = state.history[state.history.length - 1 - i];
          final haveI = r.votes.entries
              .where((e) => e.value.haveI)
              .map((e) => names[e.key] ?? e.key)
              .join(', ');
          final never = r.votes.entries
              .where((e) => !e.value.haveI)
              .map((e) => names[e.key] ?? e.key)
              .join(', ');
          return Container(
            margin: const EdgeInsets.only(bottom: 8),
            padding: const EdgeInsets.all(12),
            decoration: BoxDecoration(
              color: Colors.white.withOpacity(0.05),
              borderRadius: BorderRadius.circular(12),
              border: Border.all(color: _kTeal.withOpacity(0.1)),
            ),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(
                  '🍹 ${r.card.content}',
                  style: const TextStyle(
                    color: Colors.white,
                    fontWeight: FontWeight.w600,
                    fontSize: 13,
                  ),
                ),
                if (haveI.isNotEmpty) ...[
                  const SizedBox(height: 4),
                  Text(
                    '🙋 $haveI',
                    style: const TextStyle(color: _kTeal, fontSize: 12),
                  ),
                ],
                if (never.isNotEmpty)
                  Text(
                    '🙅 $never',
                    style: const TextStyle(color: _kCoral, fontSize: 12),
                  ),
              ],
            ),
          );
        },
      );
    }
    if (state is MemeState) {
      if (state.history.isEmpty)
        return const Center(
          child: Text(
            'No rounds completed yet',
            style: TextStyle(color: Colors.white38),
          ),
        );
      return ListView.builder(
        padding: const EdgeInsets.all(12),
        itemCount: state.history.length,
        itemBuilder: (_, i) {
          final r = state.history[state.history.length - 1 - i];
          final winner = names[r.winnerId] ?? r.winnerId ?? '?';
          final winSub = r.submissions[r.winnerId];
          return Container(
            margin: const EdgeInsets.only(bottom: 8),
            padding: const EdgeInsets.all(12),
            decoration: BoxDecoration(
              color: Colors.white.withOpacity(0.05),
              borderRadius: BorderRadius.circular(12),
              border: Border.all(color: _kPurple.withOpacity(0.12)),
            ),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(
                  'Round ${r.roundNumber}: ${r.prompt.caption}',
                  style: const TextStyle(color: Colors.white60, fontSize: 11),
                ),
                const SizedBox(height: 6),
                Row(
                  children: [
                    const Text('🏆 '),
                    Text(
                      winner,
                      style: const TextStyle(
                        color: _kYellow,
                        fontWeight: FontWeight.w700,
                      ),
                    ),
                    if (winSub != null) ...[
                      const SizedBox(width: 10),
                      _stickerImg(winSub.stickerChoice, height: 24),
                      if (winSub.caption.isNotEmpty) ...[
                        const SizedBox(width: 6),
                        Expanded(
                          child: Text(
                            '"${winSub.caption}"',
                            style: const TextStyle(
                              color: Colors.white54,
                              fontSize: 12,
                              fontStyle: FontStyle.italic,
                            ),
                            overflow: TextOverflow.ellipsis,
                          ),
                        ),
                      ],
                    ],
                  ],
                ),
              ],
            ),
          );
        },
      );
    }
    return const Center(
      child: Text(
        'No history available',
        style: TextStyle(color: Colors.white38),
      ),
    );
  }
}

// ── LAN Lobby ──────────────────────────────────────────────────────────────────
class _LanLobbyScreen extends StatefulWidget {
  const _LanLobbyScreen({required this.game});
  final OfflineGameProvider game;
  @override
  State<_LanLobbyScreen> createState() => _LanLobbyScreenState();
}

class _LanLobbyScreenState extends State<_LanLobbyScreen> {
  final _chatCtrl = TextEditingController();
  final _scrollCtrl = ScrollController();
  @override
  void dispose() {
    _chatCtrl.dispose();
    _scrollCtrl.dispose();
    super.dispose();
  }

  void _send() {
    final t = _chatCtrl.text.trim();
    if (t.isEmpty) return;
    widget.game.sendChat(t);
    _chatCtrl.clear();
    _scrollToBottom();
  }

  void _scrollToBottom() => Future.delayed(100.ms, () {
    if (_scrollCtrl.hasClients)
      _scrollCtrl.animateTo(
        _scrollCtrl.position.maxScrollExtent,
        duration: 200.ms,
        curve: Curves.easeOut,
      );
  });

  @override
  Widget build(BuildContext context) {
    final game = widget.game;
    final session = game.session;
    final players = session?.players ?? [];
    return Scaffold(
      backgroundColor: _kNavy,
      appBar: AppBar(
        backgroundColor: _kNavyLight,
        foregroundColor: Colors.white,
        title: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Text(
              session?.gameType.displayName ?? 'Lobby',
              style: const TextStyle(fontWeight: FontWeight.w800),
            ),
            Text(
              session?.packName ?? '',
              style: const TextStyle(color: Colors.white54, fontSize: 11),
            ),
          ],
        ),
        actions: [
          Padding(
            padding: const EdgeInsets.only(right: 12),
            child: Center(
              child: Container(
                padding: const EdgeInsets.symmetric(
                  horizontal: 12,
                  vertical: 4,
                ),
                decoration: BoxDecoration(
                  color: _kYellow.withOpacity(0.15),
                  borderRadius: BorderRadius.circular(20),
                  border: Border.all(color: _kYellow.withOpacity(0.3)),
                ),
                child: Text(
                  '${players.length} players',
                  style: const TextStyle(
                    color: _kYellow,
                    fontSize: 12,
                    fontWeight: FontWeight.w700,
                  ),
                ),
              ),
            ),
          ),
        ],
      ),
      body: Column(
        children: [
          Container(
            color: _kNavyLight,
            padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 10),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                const Text(
                  'PLAYERS IN LOBBY',
                  style: TextStyle(
                    color: Colors.white38,
                    fontSize: 10,
                    fontWeight: FontWeight.w700,
                    letterSpacing: 1.5,
                  ),
                ),
                const SizedBox(height: 8),
                SingleChildScrollView(
                  scrollDirection: Axis.horizontal,
                  child: Row(
                    children: players.map((p) {
                      final isHost = p.seatOrder == 0;
                      return Padding(
                        padding: const EdgeInsets.only(right: 10),
                        child: Column(
                          mainAxisSize: MainAxisSize.min,
                          children: [
                            Stack(
                              children: [
                                Container(
                                  width: 44,
                                  height: 44,
                                  decoration: BoxDecoration(
                                    shape: BoxShape.circle,
                                    color: isHost
                                        ? _kYellow.withOpacity(0.2)
                                        : _kTeal.withOpacity(0.15),
                                    border: Border.all(
                                      color: isHost ? _kYellow : _kTeal,
                                      width: 1.5,
                                    ),
                                  ),
                                  alignment: Alignment.center,
                                  child: Text(
                                    p.name[0].toUpperCase(),
                                    style: TextStyle(
                                      color: isHost ? _kYellow : _kTeal,
                                      fontWeight: FontWeight.w800,
                                      fontSize: 18,
                                    ),
                                  ),
                                ),
                                if (isHost)
                                  const Positioned(
                                    top: -2,
                                    right: -2,
                                    child: Text(
                                      '👑',
                                      style: TextStyle(fontSize: 12),
                                    ),
                                  ),
                                if (!isHost && game.isLanHost)
                                  Positioned(
                                    bottom: -2,
                                    right: -2,
                                    child: GestureDetector(
                                      onTap: () => _confirmKick(context, p),
                                      child: Container(
                                        width: 16,
                                        height: 16,
                                        decoration: const BoxDecoration(
                                          color: _kCoral,
                                          shape: BoxShape.circle,
                                        ),
                                        child: const Icon(
                                          Icons.close,
                                          size: 10,
                                          color: Colors.white,
                                        ),
                                      ),
                                    ),
                                  ),
                              ],
                            ),
                            const SizedBox(height: 4),
                            Text(
                              p.name.split(' ').first,
                              style: TextStyle(
                                color: isHost ? _kYellow : Colors.white60,
                                fontSize: 10,
                                fontWeight: FontWeight.w600,
                              ),
                            ),
                          ],
                        ),
                      );
                    }).toList(),
                  ),
                ),
              ],
            ),
          ),
          Expanded(
            child: ListenableBuilder(
              listenable: game,
              builder: (_, __) {
                final msgs = game.chatMessages;
                if (msgs.isNotEmpty)
                  WidgetsBinding.instance.addPostFrameCallback(
                    (_) => _scrollToBottom(),
                  );
                final myId = game.isLanHost
                    ? (session?.players.firstOrNull?.id ?? '')
                    : (game.clientPlayerId ?? '');
                return msgs.isEmpty
                    ? Center(
                        child: Column(
                          mainAxisSize: MainAxisSize.min,
                          children: [
                            const Text('💬', style: TextStyle(fontSize: 40)),
                            const SizedBox(height: 8),
                            const Text(
                              'Say hi to the group!',
                              style: TextStyle(
                                color: Colors.white38,
                                fontSize: 14,
                              ),
                            ),
                          ],
                        ),
                      )
                    : ListView.builder(
                        controller: _scrollCtrl,
                        padding: const EdgeInsets.fromLTRB(16, 12, 16, 4),
                        itemCount: msgs.length,
                        itemBuilder: (_, i) => _ChatBubble(
                          msg: msgs[i],
                          isMe: msgs[i].senderId == myId,
                        ),
                      );
              },
            ),
          ),
          if (!game.isLanHost)
            Container(
              margin: const EdgeInsets.symmetric(horizontal: 16, vertical: 6),
              padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 8),
              decoration: BoxDecoration(
                color: _kYellow.withOpacity(0.08),
                borderRadius: BorderRadius.circular(10),
                border: Border.all(color: _kYellow.withOpacity(0.2)),
              ),
              child: Row(
                mainAxisSize: MainAxisSize.min,
                mainAxisAlignment: MainAxisAlignment.center,
                children: const [
                  SizedBox(
                    width: 12,
                    height: 12,
                    child: CircularProgressIndicator(
                      strokeWidth: 2,
                      color: _kYellow,
                    ),
                  ),
                  SizedBox(width: 10),
                  Text(
                    'Waiting for host to start…',
                    style: TextStyle(
                      color: _kYellow,
                      fontSize: 13,
                      fontWeight: FontWeight.w600,
                    ),
                  ),
                ],
              ),
            ),
          Container(
            padding: EdgeInsets.fromLTRB(
              12,
              8,
              12,
              MediaQuery.viewInsetsOf(context).bottom + 10,
            ),
            decoration: const BoxDecoration(color: _kNavyLight),
            child: Row(
              children: [
                Expanded(
                  child: TextField(
                    controller: _chatCtrl,
                    style: const TextStyle(color: Colors.white),
                    decoration: InputDecoration(
                      hintText: 'Chat…',
                      hintStyle: const TextStyle(color: Colors.white38),
                      filled: true,
                      fillColor: Colors.white.withOpacity(0.07),
                      border: OutlineInputBorder(
                        borderRadius: BorderRadius.circular(24),
                        borderSide: BorderSide.none,
                      ),
                      contentPadding: const EdgeInsets.symmetric(
                        horizontal: 16,
                        vertical: 10,
                      ),
                      isDense: true,
                    ),
                    onSubmitted: (_) => _send(),
                    textInputAction: TextInputAction.send,
                  ),
                ),
                const SizedBox(width: 8),
                GestureDetector(
                  onTap: _send,
                  child: Container(
                    width: 44,
                    height: 44,
                    decoration: const BoxDecoration(
                      color: _kYellow,
                      shape: BoxShape.circle,
                    ),
                    child: const Icon(
                      Icons.send_rounded,
                      color: _kNavy,
                      size: 20,
                    ),
                  ),
                ),
              ],
            ),
          ),
        ],
      ),
    );
  }

  void _confirmKick(BuildContext context, OfflinePlayer p) => showDialog(
    context: context,
    builder: (_) => AlertDialog(
      backgroundColor: _kNavyLight,
      title: Text(
        'Kick ${p.name}?',
        style: const TextStyle(color: Colors.white),
      ),
      content: const Text(
        'They will be removed from the lobby.',
        style: TextStyle(color: Colors.white60),
      ),
      actions: [
        TextButton(
          onPressed: () => Navigator.pop(context),
          child: const Text('Cancel', style: TextStyle(color: Colors.white54)),
        ),
        FilledButton(
          onPressed: () {
            Navigator.pop(context);
            widget.game.kickLanPlayer(p.id);
          },
          style: FilledButton.styleFrom(backgroundColor: _kCoral),
          child: const Text('Kick'),
        ),
      ],
    ),
  );
}

class _ChatBubble extends StatelessWidget {
