class _GameOverScreen extends StatelessWidget {
  const _GameOverScreen({required this.game});
  final OfflineGameProvider game;
  @override
  Widget build(BuildContext context) {
    final state = game.state;
    final names = {
      for (final p in game.session?.players ?? <OfflinePlayer>[]) p.id: p.name,
    };
    return Scaffold(
      backgroundColor: _kNavy,
      appBar: AppBar(
        backgroundColor: _kNavyLight,
        foregroundColor: Colors.white,
        title: const Text(
          'Game Over 🏆',
          style: TextStyle(fontWeight: FontWeight.w800),
        ),
      ),
      body: DefaultTabController(
        length: 2,
        child: Column(
          children: [
            Container(
              color: _kNavyLight,
              child: const TabBar(
                labelColor: _kYellow,
                unselectedLabelColor: Colors.white38,
                indicatorColor: _kYellow,
                tabs: [
                  Tab(text: '🏆 Scores'),
                  Tab(text: '📖 History'),
                ],
              ),
            ),
            Expanded(
              child: TabBarView(
                children: [
                  _buildScores(state, names),
                  _HistorySheet(game: game),
                ],
              ),
            ),
            Padding(
              padding: const EdgeInsets.all(16),
              child: FilledButton.icon(
                onPressed: () =>
                    Navigator.of(context).popUntil((r) => r.isFirst),
                style: FilledButton.styleFrom(
                  backgroundColor: _kYellow,
                  foregroundColor: _kNavy,
                  minimumSize: const Size(double.infinity, 52),
                  shape: RoundedRectangleBorder(
                    borderRadius: BorderRadius.circular(14),
                  ),
                ),
                icon: const Icon(Icons.home_rounded),
                label: const Text(
                  'Back to Menu',
                  style: TextStyle(fontWeight: FontWeight.w800, fontSize: 15),
                ),
              ),
            ),
          ],
        ),
      ),
    );
  }

  Widget _buildScores(GameEngineState? state, Map<String, String> names) {
    List<MapEntry<String, int>> scores = [];
    if (state is TodState)
      scores =
          state.scores.entries
              .map((e) => MapEntry(e.key, e.value.points))
              .toList()
            ..sort((a, b) => b.value.compareTo(a.value));
    else if (state is NhieState)
      scores = state.scores.entries.toList()
        ..sort((a, b) => b.value.compareTo(a.value));
    else if (state is MemeState)
      scores = state.scores.entries.toList()
        ..sort((a, b) => b.value.compareTo(a.value));
    return ListView.builder(
      padding: const EdgeInsets.all(20),
      itemCount: scores.length + 1,
      itemBuilder: (_, i) {
        if (i == 0)
          return Padding(
            padding: const EdgeInsets.only(bottom: 24),
            child: Column(
              children: [
                const Text(
                  '🏆',
                  style: TextStyle(fontSize: 64),
                ).animate().scale(
                  begin: const Offset(0, 0),
                  end: const Offset(1, 1),
                  duration: 600.ms,
                  curve: Curves.elasticOut,
                ),
                const SizedBox(height: 8),
                const Text(
                  'Final Scores',
                  style: TextStyle(
                    color: Colors.white,
                    fontSize: 28,
                    fontWeight: FontWeight.w900,
                  ),
                ),
              ],
            ),
          );
        final e = scores[i - 1];
        final medals = ['🥇', '🥈', '🥉'];
        final isTop = i <= 3;
        return Container(
              margin: const EdgeInsets.only(bottom: 10),
              padding: const EdgeInsets.symmetric(horizontal: 20, vertical: 14),
              decoration: BoxDecoration(
                gradient: isTop
                    ? LinearGradient(
                        colors: [
                          _kYellow.withOpacity(i == 1 ? 0.15 : 0.08),
                          Colors.transparent,
                        ],
                        begin: Alignment.centerLeft,
                        end: Alignment.centerRight,
                      )
                    : null,
                color: isTop ? null : Colors.white.withOpacity(0.05),
                borderRadius: BorderRadius.circular(16),
                border: isTop
                    ? Border.all(
                        color: _kYellow.withOpacity(i == 1 ? 0.3 : 0.1),
                      )
                    : null,
              ),
              child: Row(
                children: [
                  Text(
                    i <= 3 ? medals[i - 1] : '$i.',
                    style: const TextStyle(fontSize: 26),
                  ),
                  const SizedBox(width: 14),
                  Expanded(
                    child: Text(
                      names[e.key] ?? e.key,
                      style: TextStyle(
                        color: i == 1 ? _kYellow : Colors.white,
                        fontWeight: FontWeight.w700,
                        fontSize: 17,
                      ),
                    ),
                  ),
                  Text(
                    '${e.value}',
                    style: TextStyle(
                      color: i == 1 ? _kYellow : Colors.white60,
                      fontWeight: FontWeight.w900,
                      fontSize: 20,
                    ),
                  ),
                  const SizedBox(width: 4),
                  const Text(
                    'pts',
                    style: TextStyle(color: Colors.white38, fontSize: 12),
                  ),
                ],
              ),
            )
            .animate(delay: Duration(milliseconds: i * 80))
            .fadeIn()
            .slideX(begin: 0.1, end: 0);
      },
    );
  }
}
